BEGIN TRANSACTION;
CREATE TABLE activity (session TEXT PRIMARY KEY, turn TEXT, status TEXT, started REAL);
CREATE TABLE comets (session TEXT PRIMARY KEY, turn TEXT, queued REAL, source INTEGER, started REAL);
CREATE TABLE controller_credentials (principal TEXT PRIMARY KEY, digest TEXT NOT NULL, scopes TEXT NOT NULL, active INTEGER NOT NULL);
CREATE TABLE controller_events (sequence INTEGER PRIMARY KEY, payload TEXT NOT NULL);
CREATE TABLE controller_meta (id INTEGER PRIMARY KEY, payload TEXT NOT NULL);
CREATE TABLE controller_requests (sequence INTEGER PRIMARY KEY, request TEXT NOT NULL, receipt TEXT NOT NULL, principal TEXT NOT NULL, phase TEXT NOT NULL, created REAL NOT NULL, mode_revision INTEGER NOT NULL);
CREATE TABLE display_v3 (id INTEGER PRIMARY KEY, snapshot TEXT, looping INTEGER, rendered REAL);
CREATE TABLE integration_meta (id INTEGER PRIMARY KEY, sequence INTEGER NOT NULL);
CREATE TABLE integration_requests (sequence INTEGER PRIMARY KEY, principal TEXT, request TEXT, receipt TEXT, phase TEXT, created REAL, revision TEXT);
CREATE TABLE line_prefs (line_id TEXT PRIMARY KEY,project TEXT,signature INTEGER DEFAULT 0);
CREATE TABLE locate (id INTEGER PRIMARY KEY,line_id TEXT,started REAL);
CREATE TABLE map_pending (id INTEGER PRIMARY KEY,payload TEXT);
CREATE TABLE map_settings (id INTEGER PRIMARY KEY,style TEXT,coverage TEXT,rotation INTEGER,flip_x INTEGER,flip_y INTEGER);
CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT);
CREATE TABLE projects (id TEXT PRIMARY KEY,name TEXT,color TEXT,roots TEXT);
CREATE TABLE receipts (session TEXT PRIMARY KEY, turn TEXT, completed REAL, observed INTEGER);
CREATE TABLE sessions (id TEXT PRIMARY KEY, turn TEXT, status TEXT, updated REAL);
CREATE TABLE shared_ack (id INTEGER PRIMARY KEY, payload TEXT, result TEXT);
CREATE TABLE shared_input (id INTEGER PRIMARY KEY, source TEXT, generation INTEGER, config TEXT, envelope TEXT, received REAL, connection TEXT, error TEXT, backup TEXT);
CREATE TABLE shared_stale (session TEXT PRIMARY KEY);
CREATE TABLE shared_suppressed_waves (session TEXT PRIMARY KEY, epoch REAL);
CREATE TABLE slots (session TEXT PRIMARY KEY, slot INTEGER UNIQUE);
CREATE TABLE task_info (session TEXT PRIMARY KEY,title TEXT,cwd TEXT,project TEXT,manual_project TEXT,turn TEXT,started REAL);
CREATE TABLE waits (session TEXT, turn TEXT, key TEXT, kind TEXT, tool TEXT, PRIMARY KEY(session, turn, key));
COMMIT;
